INSERT OR IGNORE INTO questions (id, module_key, type_key, difficulty, title, instructions, prompt, passage, correct_answer, alternative_answers, model_answer, explanation, scoring_config, score_weight, topic, content_json, estimated_seconds, audio_asset_id, image_asset_id, source_reference, admin_notes, ai_confidence, status, current_version, created_by, reviewed_by, created_at, updated_at, published_at) VALUES ('qst_seed_reading_writing_fill_blanks_2', 'reading', 'reading_writing_fill_blanks', 'hard', 'Reading and Writing Fill in the Blanks — Marine biology 2', 'A passage with blanks; the student selects the best word from a dropdown.', 'Select the word that best fits each blank.', 'Behavioural researchers distinguish between habits, which are triggered by context, and intentions, which depend on deliberate attention. Programmes that rely only on information campaigns tend to fade once novelty passes, whereas those that redesign the surrounding environment produce changes that persist long after the intervention ends. Researchers describe this pattern as [[1]] and broadly [[2]].', '1: consistent; 2: predictable', '[]', '', 'Sample item written for this platform to demonstrate the Reading and Writing Fill in the Blanks task format.', '{"criteria":{"reading":1,"writing":1},"maxScore":10}', 1, 'Marine biology', '{"blanks":[{"index":1,"answer":"consistent","choices":["consistent","reluctant","temporary","hidden"]},{"index":2,"answer":"predictable","choices":["predictable","invisible","hostile","random"]}],"wordBank":["consistent","reluctant","temporary","hidden","predictable","invisible","hostile","random"]}', 120, NULL, NULL, 'Original sample content authored in-house.', 'Seed example. Replace with reviewed production content before launch.', 0.77, 'draft', 1, NULL, NULL, '2026-01-20T09:45:00.000Z', '2026-01-20T09:45:00.000Z', NULL);
