INSERT OR IGNORE INTO question_versions (id, question_id, version_number, snapshot, status, change_note, created_by, created_at) VALUES ('qst_seed_reading_fill_blanks_2_v1', 'qst_seed_reading_fill_blanks_2', 1, '{"id":"qst_seed_reading_fill_blanks_2","module":"reading","type":"reading_fill_blanks","difficulty":"hard","title":"Reading Fill in the Blanks — Water management 2","instructions":"The student drags words from a word bank into the blanks in a passage.","prompt":"Select the word that best fits each blank.","passage":"Behavioural researchers distinguish between habits, which are triggered by context, and intentions, which depend on deliberate attention. Programmes that rely only on information campaigns tend to fade once novelty passes, whereas those that redesign the surrounding environment produce changes that persist long after the intervention ends. Researchers describe this pattern as [[1]] and broadly [[2]].","correctAnswer":"1: consistent; 2: predictable","alternativeAnswers":[],"modelAnswer":"","explanation":"Sample item written for this platform to demonstrate the Reading Fill in the Blanks task format.","scoringConfig":{"criteria":{"reading":1},"maxScore":5},"scoreWeight":1,"topic":"Water management","tags":["water-management","reading","hard"],"estimatedSeconds":120,"sourceReference":"Original sample content authored in-house.","adminNotes":"Seed example. Replace with reviewed production content before launch.","aiConfidence":0.82,"status":"approved","content":{"blanks":[{"index":1,"answer":"consistent","choices":["consistent","reluctant","temporary","hidden"]},{"index":2,"answer":"predictable","choices":["predictable","invisible","hostile","random"]}],"wordBank":["consistent","reluctant","temporary","hidden","predictable","invisible","hostile","random"]},"options":[],"audio":null,"image":null,"usage":{"attempts":14,"avgScore":61,"correctRate":0.72}}', 'approved', 'Seed import', NULL, '2026-01-26T09:27:00.000Z');
